/**
 * @param {string} s
 * @return {number}
 */
var distinctSubseqII = function (s) {
    let MOD = 1_000_000_007;
    let n = s.length;
    const dp = new Array(n + 1);
    dp[0] = 1;
    const last = Array(26).fill(-1);

    for (let i = 0; i < n; ++i) {
        const pos = s.charCodeAt(i) - 97;

        dp[i + 1] = (dp[i] * 2) % MOD;

        if (last[pos] >= 0) {
            dp[i + 1] -= dp[last[pos]];
        }

        dp[i + 1] %= MOD;
        last[pos] = i;
    }

    return (dp[n] - 1 + MOD) % MOD;
};
